mapper.insert:
INSERT INTO public.om_lighthouse_log
(lh_json, page_url, page_status, page_no, rgstr_dt)
VALUES(#{lh_json}, #{page_url}, #{page_status}, #{page_no}, now());

mapper.select:
SELECT * FROM om_lighthouse_log oll 
WHERE page_url = #{page_url}
	AND page_status = #{page_status}

		AND page_no = #{page_no}

ORDER BY rgstr_dt DESC  
LIMIT 1
